"use strict";const{handleRpcRequest}=require("../backend-sql/src/rpc-router"),{initDatabase}=require("../backend-sql/src/db/database"),{initSchema}=require("../backend-sql/src/db/schema-init");try{const t=initDatabase();initSchema(t)}catch{}module.exports=async(t,e)=>{if(e.setHeader("Access-Control-Allow-Credentials","true"),e.setHeader("Access-Control-Allow-Origin","*"),e.setHeader("Access-Control-Allow-Methods","GET,OPTIONS,PATCH,DELETE,POST,PUT"),e.setHeader("Access-Control-Allow-Headers","X-CSRF-Token, X-Requested-With, Accept, Accept-Version, Content-Length, Content-MD5, Content-Type, Date, X-Api-Version, Authorization"),t.method==="OPTIONS")return e.status(200).end();if(t.method==="GET")return e.status(200).json({status:"ok",server:"HSE Vercel Serverless API",endpoint:"/api/exec",timestamp:new Date().toISOString()});if(t.method!=="POST")return e.status(405).json({success:!1,message:"Method Not Allowed"});let s=t.body;if(typeof s=="string")try{s=JSON.parse(s)}catch{return e.status(400).json({success:!1,message:"Invalid JSON payload"})}try{const r=handleRpcRequest(s);return e.status(200).json(r)}catch(r){return e.status(500).json({success:!1,message:r.message||"Internal Server Error",errorCode:"SERVERLESS_INTERNAL_ERROR"})}};
